r"""Library name census: for each C++11 header that cpp11 ships, one tiny TU per name from the header's C++11
synopsis, compiled with cpp11 -S alone. A name is 'present' when the TU compiles. Writes <out>\census.tsv, prints
the missing names per header, and against census-baseline.tsv beside this script the names gained and lost (a
lost name exits 1). Written by Fable 5.1 for the 1.30 verification, 2026-10-28.
usage: python -I census.py [-j 6] [--cpp11 <cpp11.exe>] [--out <dir>] [--freeze]"""
import os, sys, subprocess, concurrent.futures
from collections import defaultdict
HERE = os.path.dirname(os.path.abspath(__file__))
_a = sys.argv[1:]
CPP11 = os.path.abspath(_a[_a.index("--cpp11") + 1] if "--cpp11" in _a else os.path.join(HERE, *([".."] * 6), "GRIDEd", "x64", "Release", "cpp11.exe"))
OUT = os.path.abspath(_a[_a.index("--out") + 1] if "--out" in _a else os.path.join(os.environ.get("TEMP", HERE), "cpp11-census"))
BASE = os.path.join(HERE, "census-baseline.tsv")

# (header, kind, name): kind T = type/class template usable as `sizeof(std::X<...>)` or typedef; F = function (taking address or calling);
# the probe text is given explicitly where the generic form would not do.
def T(h, n, args=""): return (h, n, "typedef std::%s probe_t; probe_t *p = 0;" % (n + args if ("<" not in n and args) else n))
def V(h, n): return (h, n, "int probe_k = sizeof(&std::%s);" % n)          # object or function (address)
def E(h, n, expr): return (h, n, "void probe() { (void)(%s); }" % expr)  # expression compiles
def M(h, n, txt): return (h, n, txt)
PRE = {"cstdio": "std::FILE *f = stdout; char buf[8] = \"\"; va_list ap; (void)ap;", "cstring": "char buf[8] = \"\";", "cctype": "", "ctime": "std::time_t t = 0; std::tm tmv = std::tm(); char buf[8];", "cstdlib": "char buf[8] = \"\"; (void)buf;"}
def EP(h, n, expr): return (h, n, "#include <cstdarg>\nextern \"C\" int probe_cmp(const void *, const void *); void probe_h() {}\nvoid probe() { %s (void)(%s); }" % (PRE.get(h, ""), expr))

