def tu(h, txt):
    incs = HEADERS_FOR.get(h, [h])
    pre = "".join("#include <%s>\n" % i for i in incs) + ("enum E { e0 };\n" if h == "type_traits" else "")
    return pre + txt + "\nint main() { return 0; }\n"

def one(i, item):
    h, n, txt = item
    src = os.path.join(OUT, "n%04d.cpp" % i)
    with open(src, "w", encoding="utf-8", newline="\n") as f: f.write(tu(h, txt))
    try:
        p = subprocess.run([CPP11, "-nologo", "-S", src, "-o", src[:-4] + ".s", "-arch", "x86_64-windows", "-O0"], capture_output=True, text=True, errors="replace", timeout=60, cwd=OUT)
        rc, out = p.returncode, (p.stdout or "") + (p.stderr or "")
    except subprocess.TimeoutExpired:
        rc, out = -999, "timeout"
    ok = rc == 0 and os.path.exists(src[:-4] + ".s")
    msg = ""
    if not ok:
        for l in out.splitlines():
            if "error" in l: msg = l.strip(); break
        msg = msg.split(": error: ")[-1][:110]
    return (h, n, "present" if ok else ("CRASH" if rc not in (0, 1, -999) else "missing"), msg)

def main():
    j = 6
    a = sys.argv[1:]
    if "-j" in a: j = int(a[a.index("-j") + 1])
    os.makedirs(OUT, exist_ok=True)
    with concurrent.futures.ThreadPoolExecutor(max_workers=j) as ex:
        rows = list(ex.map(lambda t: one(*t), enumerate(C)))
    with open(os.path.join(OUT, "census.tsv"), "w", encoding="utf-8") as f:
        for r in rows: f.write("\t".join(r) + "\n")
    by = defaultdict(lambda: [0, 0, []])
    for h, n, st, msg in rows:
        by[h][0 if st == "present" else 1] += 1
        if st != "present": by[h][2].append("%s%s" % (n, " [CRASH]" if st == "CRASH" else ""))
    for h in sorted(by):
        p, m, miss = by[h]
        print("%-17s present %3d  missing %3d : %s" % ("<%s>" % h, p, m, ", ".join(miss)))
    print("total present %d missing %d" % (sum(1 for r in rows if r[2] == "present"), sum(1 for r in rows if r[2] != "present")))
    if "--freeze" in a:
        with open(BASE, "w", encoding="utf-8", newline="\n") as f:
            for h, n, st, msg in rows: f.write("%s\t%s\t%s\n" % (h, n, st))
        print("baseline written: " + BASE)
        return 0
    if os.path.exists(BASE):
        was = {}
        for l in open(BASE, encoding="utf-8"):
            h, n, st = l.rstrip("\n").split("\t")
            was[(h, n)] = st
        gained = [r for r in rows if r[2] == "present" and was.get((r[0], r[1])) not in (None, "present")]
        lost = [r for r in rows if r[2] != "present" and was.get((r[0], r[1])) == "present"]
        print("gained against the baseline: %d" % len(gained))
        for r in gained: print("  <%s> %s" % (r[0], r[1]))
        print("lost against the baseline: %d" % len(lost))
        for r in lost: print("  <%s> %s: %s" % (r[0], r[1], r[3]))
        if lost: return 1
    return 0

sys.exit(main())
